function Questions({stored,save,router}:{stored:Stored;save:(x:Stored)=>void;router:ReturnType<typeof useRouter>}){const [cost,setCost]=useState(stored.inputs.costPerItem?.toString()??''),[ads,setAds]=useState(stored.inputs.monthlyAdSpend===0?'':stored.inputs.monthlyAdSpend?.toString()??'');const [unknown,setUnknown]=useState(false),[noAds,setNoAds]=useState(stored.inputs.monthlyAdSpend===0);const [issue,setIssue]=useState(''),[busy,setBusy]=useState(false);const submitting=useRef(false);const go=async(skip=false)=>{if(submitting.current)return;const generation=sourceGeneration;if((cost!==''&&(!Number.isFinite(Number(cost))||Number(cost)<0))||(ads!==''&&(!Number.isFinite(Number(ads))||Number(ads)<0))){setIssue('Enter a valid amount of zero or more.');return}const changed=(skip?undefined:cost===''?undefined:Number(cost))!==stored.inputs.costPerItem||(skip?undefined:noAds?0:ads===''?undefined:Number(ads))!==stored.inputs.monthlyAdSpend;if(changed&&!activeRows.length&&stored.source!=='demo'){setIssue(stored.source==='csv'?'To update these values, upload your activity again.':'To update these values, connect your sandbox again.');return}const inputs={...stored.inputs,costPerItem:skip||cost===''?undefined:Number(cost),monthlyAdSpend:skip?undefined:noAds?0:ads===''?undefined:Number(ads)};submitting.current=true;setBusy(true);try{const analysis=stored.source==='sandbox'&&activeRows.length?reanalyzeSandboxRows(activeRows,stored.analysis,inputs):activeRows.length?{...analyze(activeRows,inputs),...(stored.analysis.product_grouping?{product_grouping:stored.analysis.product_grouping}:{})}:stored.analysis;if(generation!==sourceGeneration)return;save({...stored,inputs,analysis});router.push('/read')}catch(e){if(generation===sourceGeneration)setIssue((e as Error).message)}finally{submitting.current=false;setBusy(false)}};return <main className="screen"><Header source={stored.sandboxMode==='demo'?'sandbox-demo':stored.source} back="/"/><div className="wrap questions"><h1>Two quick questions<br/>before your results</h1><p className="intro">Both optional. PayPal can’t see your costs.</p><Card><h2>What does one item cost you to make and ship?</h2><p>So we can show what you really earn per sale.</p><label className="amount"><span>$</span><input data-analytics-id="question_cost" inputMode="decimal" value={cost} onChange={e=>{setCost(e.target.value);setUnknown(false)}} placeholder="12"/><em>per item</em></label><div className="field-note">A rough guess is fine.<Button data-analytics-id="question_unknown_cost" className={unknown?'selected-chip':''} kind="quiet" onClick={()=>{setCost('');setUnknown(!unknown)}}>I don’t know</Button></div></Card><Card><h2>How much do you spend on ads each month?</h2><p>So we know if your sales come from ads.</p><label className="amount"><span>$</span><input data-analytics-id="question_ads" inputMode="decimal" value={ads} onChange={e=>{setAds(e.target.value);setNoAds(false)}} placeholder="0"/><em>a month</em></label><div className="field-note">Any platform counts.<Button data-analytics-id="question_no_ads" className={noAds?'selected-chip':''} kind="quiet" onClick={()=>{setAds('');setNoAds(!noAds)}}>I don’t run ads</Button></div></Card>{issue&&<p className="error" role="alert">{issue}</p>}<Button data-analytics-id="question_continue" disabled={busy} onClick={()=>go()}>Show my results</Button><Button data-analytics-id="question_skip" kind="quiet" disabled={busy} onClick={()=>go(true)}>Skip both</Button></div></main>}

function MoneyCard({stored}:{stored:Stored}){const a=stored.analysis,total=a.money_map;if(!a.period.start)return null;const reached=total.came_in-total.paypal_fees-total.refunds;const entries=[['PayPal kept',total.paypal_fees,'fees'],['Refunds',total.refunds,'refunds']];return <Card className="money-card"><p className="source-line">{periodLabel(a.period.start,a.period.end)}</p><h2>What PayPal shows</h2><div className="came"><span>Came in</span><b>{reconciledMoney(total.came_in,a.currency)}</b></div><div className="money-bar">{[{value:reached,type:'kept'},...entries.map(([,value,type])=>({value:Number(value),type:String(type)}))].map(x=><i key={x.type} className={x.type} style={{width:`${Math.max(2,Math.max(0,x.value)/total.came_in*100)}%`}}>{x.type==='kept'&&'reached your account'}</i>)}</div>{entries.map(([label,value,type])=><div className="money-row" key={String(label)}><span><i className={String(type)}/>{label}</span><b>{reconciledMoney(-Number(value),a.currency,true)}</b></div>)}<div className="kept"><span><i/>Reached your account</span><b>{reconciledMoney(reached,a.currency,true)}</b></div><Link data-analytics-id="read_math" href="/read?math=1"><svg aria-hidden="true" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><rect x="4" y="4" width="16" height="16" rx="2"/><path d="M4 10h16M10 10v10"/></svg> Show the math</Link></Card>}

function Read({stored,save,router,math}:{stored:Stored;save:(x:Stored)=>void;router:ReturnType<typeof useRouter>;math:boolean}){const [quietRecorded,setQuietRecorded]=useState(false),[returnIssue,setReturnIssue]=useState(''),[returnBusy,setReturnBusy]=useState(false);useEffect(()=>{try{setQuietRecorded(!!stored.shopKey&&!!localStorage.getItem(`wtes_quiet_offer_${stored.shopKey}`))}catch{setQuietRecorded(false)}},[stored.shopKey,stored.answers.quiet_offer_started]);const a=stored.analysis,top=a.ranked_leaks[0],risk=a.risks?.[0],shop=a.product_grouping?.source==='fallback'?'':a.product_grouping?.shop?.replace(/^this shop sells\s*/i,'').replace(/[.\s]+$/,'');return <main className="screen"><Header source={stored.sandboxMode==='demo'?'sandbox-demo':stored.source}/><div className="wrap read"><p className="source-line">{stored.source==='demo'?'Fictional sample jewelry shop':stored.source==='sandbox'?'PayPal sandbox':'Your PayPal activity'}</p>{shop&&<p className="source-line">Your shop sells {shop}.</p>}<h1>Here are your results.</h1>{stored.source==='demo'&&hasRealTabBackup()&&<><button data-analytics-id="back_link" className="button line" disabled={returnBusy} onClick={()=>{setReturnBusy(true);setReturnIssue('');void leaveBrowserDemo().then(ok=>{if(ok)window.location.assign('/read');else{setReturnBusy(false);setReturnIssue('Your saved source is unavailable. Sign in and reopen it or upload your file again.')}})}}>Return to your shop</button>{returnIssue&&<p role="alert">{returnIssue} <Link href="/">Open your activity</Link></p>}</>}<Link className="button line" data-analytics-id="business_numbers_open" href="/business-numbers">See your business numbers</Link>{(a.gaps||[]).filter(gap=>gap.startsWith('Some transaction statuses')).map(gap=><p className="small" key={gap}>{gap}</p>)}{stored.storageNotice&&<p className="small">We couldn&apos;t save this file to your account. Your results are below; upload again later to save it.</p>}<MonthlyChart stored={stored}/>{stored.uploads&&<details className="upload-details"><summary>Manage uploaded files</summary><UploadList stored={stored} save={save}/></details>}<div className={`read-grid ${a.quick_win?'':'no-quick'} ${a.ranked_leaks.length>1?'':'no-other'}`}><MoneyCard stored={stored}/><TopLeak leak={top} stored={stored} save={save}/>{a.quick_win&&(a.quick_win.id==='unpaid_invoices'?<QuickWin stored={stored}/>:<Card><Tag>QUICK WIN</Tag><h2>{a.quick_win.card?.title}</h2><strong className="big-number">{money(a.quick_win.one_off_amount||0,a.currency)}</strong><p>{a.quick_win.card?.so_what}</p><Link data-analytics-id="read_top_leak" className="button line" href={`/leak/${a.quick_win.id}`}>See what to do</Link></Card>)}{a.ranked_leaks.length>1&&<OtherLeaks stored={stored} save={save}/>}{quietRecorded&&quietSummary(stored).people.length>0&&!a.ranked_leaks.some(l=>l.id==='lapsed_buyers')&&<QuietOffer stored={stored} save={save}/>}<BundleCard stored={stored} save={save}/><BestSellers stored={stored}/> {risk&&<Risk risk={risk} stored={stored}/>}</div><Link data-analytics-id="read_plan" className="button line plan-link" href="/plan">See your plan</Link></div>{math&&<MathDrawer stored={stored} close={()=>router.push('/read')}/>}</main>}

